import os, sys, datetime
pdf_path = '/workspace/briefing.pdf'
out_path = '/workspace/comments.txt'

if not os.path.exists(pdf_path):
    sys.exit(f'PDF not found: {pdf_path}')

# Install pikepdf if needed
try:
    import pikepdf
except Exception:
    import subprocess, sys
    subprocess.check_call([sys.executable, '-m', 'pip', 'install', '--quiet', 'pikepdf'])
    import pikepdf


def pdf_date_to_iso(s):
    if not s:
        return ''
    try:
        s = str(s)
        if s.startswith('D:'):
            s = s[2:]
        digits = ''.join(ch for ch in s if ch.isdigit())
        digits = (digits + '0'*14)[:14]
        dt = datetime.datetime.strptime(digits, '%Y%m%d%H%M%S')
        return dt.isoformat(sep=' ')
    except Exception:
        return str(s)


def to_str(v):
    if v is None:
        return ''
    try:
        return str(v)
    except Exception:
        try:
            return bytes(v).decode('utf-8', 'ignore')
        except Exception:
            return ''

annots = []
with pikepdf.open(pdf_path) as pdf:
    for pageno, page in enumerate(pdf.pages, start=1):
        arr = page.get('/Annots', None)
        if not arr:
            continue
        for aref in arr:
            try:
                a = aref.get_object()
            except Exception:
                continue
            subtype = to_str(a.get('/Subtype', ''))
            if subtype.startswith('/'):
                subtype = subtype[1:]
            entry = {
                'page': pageno,
                'type': subtype,
                'author': to_str(a.get('/T', '')),
                'subject': to_str(a.get('/Subj', '')),
                'created': pdf_date_to_iso(a.get('/CreationDate', '')),
                'modified': pdf_date_to_iso(a.get('/M', '')),
            }
            contents = to_str(a.get('/Contents', ''))
            rich = to_str(a.get('/RC', ''))
            texts = []
            for t in [contents.strip(), rich.strip(), entry['subject'].strip()]:
                if t and t not in texts:
                    texts.append(t)
            entry['text'] = '\n'.join(texts)
            annots.append(entry)

with open(out_path, 'w', encoding='utf-8') as f:
    if not annots:
        f.write('No comments or annotations found in the PDF.\n')
    else:
        for i, e in enumerate(annots, 1):
            f.write(f'Annotation {i}\n')
            f.write(f'- Page: {e["page"]}\n')
            f.write(f'- Type: {e["type"]}\n')
            if e['author']:
                f.write(f'- Author: {e["author"]}\n')
            if e['created']:
                f.write(f'- Created: {e["created"]}\n')
            if e['modified']:
                f.write(f'- Modified: {e["modified"]}\n')
            if e['text']:
                f.write('- Text:\n')
                f.write(e['text'] + '\n')
            else:
                f.write('- Text: (none)\n')
            f.write('\n')

print(f'Wrote {len(annots)} annotations to {out_path}')
